from pathlib import Path
import re
p=Path('Main.gd'); s=p.read_text(encoding='utf-8'); orig=s
s=s.replace('const RUN_SAVE_VERSION := 6','const RUN_SAVE_VERSION := 7',1)
if 'const RUN_SAVE_VERSION := 7' not in s: raise SystemExit('save version anchor failed')
s=s.replace('var map_visible: bool = true\n','var map_visible: bool = true\nvar visible_now: Array = []\nvar floor_rooms: Array = []\n',1)
helpers='''func make_bool_grid(fill_value: bool = false) -> Array:\n\tvar grid: Array = []\n\tfor y in range(MAP_H):\n\t\tvar row: Array = []\n\t\tfor x in range(MAP_W): row.append(fill_value)\n\t\tgrid.append(row)\n\treturn grid\n\n\nfunc room_index_at(p: Vector2i) -> int:\n\tfor i in range(floor_rooms.size()):\n\t\tvar r: Rect2i = floor_rooms[i]\n\t\tif r.has_point(p): return i\n\treturn -1\n\n\nfunc random_cell_in_room(r: Rect2i) -> Vector2i:\n\treturn Vector2i(rng.randi_range(r.position.x, r.end.x - 1), rng.randi_range(r.position.y, r.end.y - 1))\n\n\nfunc carve_room_rect(r: Rect2i) -> void:\n\tfor y in range(r.position.y, r.end.y):\n\t\tfor x in range(r.position.x, r.end.x):\n\t\t\tif x > 0 and y > 0 and x < MAP_W - 1 and y < MAP_H - 1: map[y][x] = "."\n\n\nfunc carve_one_tile_corridor(a: Vector2i, b: Vector2i) -> void:\n\tvar p: Vector2i = a\n\tvar horizontal_first: bool = rng.randi_range(0, 1) == 0\n\tif horizontal_first:\n\t\twhile p.x != b.x:\n\t\t\tp.x += 1 if b.x > p.x else -1; map[p.y][p.x] = "."\n\t\twhile p.y != b.y:\n\t\t\tp.y += 1 if b.y > p.y else -1; map[p.y][p.x] = "."\n\telse:\n\t\twhile p.y != b.y:\n\t\t\tp.y += 1 if b.y > p.y else -1; map[p.y][p.x] = "."\n\t\twhile p.x != b.x:\n\t\t\tp.x += 1 if b.x > p.x else -1; map[p.y][p.x] = "."\n\n\nfunc build_room_corridor_floor() -> void:\n\tmap.clear(); floor_rooms.clear()\n\tfor y in range(MAP_H):\n\t\tvar row: Array = []\n\t\tfor x in range(MAP_W): row.append("#")\n\t\tmap.append(row)\n\tvar zones: Array = [Rect2i(1,1,9,5),Rect2i(11,1,9,5),Rect2i(21,1,9,5),Rect2i(1,8,9,5),Rect2i(11,8,9,5),Rect2i(21,8,9,5)]\n\tvar order: Array = [0,1,2,3,4,5]\n\tfor i in range(order.size()-1,0,-1):\n\t\tvar j: int = rng.randi_range(0,i); var t: int = int(order[i]); order[i]=order[j]; order[j]=t\n\tvar room_count: int = rng.randi_range(4,6)\n\tfor n in range(room_count):\n\t\tvar z: Rect2i = zones[order[n]]\n\t\tvar rw: int = rng.randi_range(4,mini(8,z.size.x)); var rh: int = rng.randi_range(3,mini(5,z.size.y))\n\t\tvar room := Rect2i(rng.randi_range(z.position.x,z.end.x-rw),rng.randi_range(z.position.y,z.end.y-rh),rw,rh)\n\t\tfloor_rooms.append(room); carve_room_rect(room)\n\tvar connected: Array[int] = [0]\n\tfor i in range(1,floor_rooms.size()):\n\t\tvar c: Vector2i = floor_rooms[i].get_center(); var best: int = connected[0]; var best_dist: int = 99999\n\t\tfor j in connected:\n\t\t\tvar jc: Vector2i = floor_rooms[j].get_center(); var d: int = absi(c.x-jc.x)+absi(c.y-jc.y)\n\t\t\tif d < best_dist: best_dist=d; best=j\n\t\tcarve_one_tile_corridor(c,floor_rooms[best].get_center()); connected.append(i)\n\n\nfunc draw_explored_minimap_portrait() -> void:\n\tif not validate_grid(explored): return\n\tvar cell: float = 4.0; var origin: Vector2 = Vector2(552, 472)\n\tdraw_rect(Rect2(origin-Vector2(6,6),Vector2(MAP_W*cell+12,MAP_H*cell+12)),Color(0.02,0.03,0.04,0.82))\n\tfor y in range(MAP_H):\n\t\tfor x in range(MAP_W):\n\t\t\tif not bool(explored[y][x]) or str(map[y][x]) == "#": continue\n\t\t\tvar col: Color = Color("#e2c95d") if str(map[y][x]) == ">" else Color("#7a8290")\n\t\t\tdraw_rect(Rect2(origin+Vector2(x*cell,y*cell),Vector2(cell,cell)),col)\n\tdraw_circle(origin+Vector2(player.x*cell+2,player.y*cell+2),3.5,Color("#72c7e8"))\n'''
marker='\n\nfunc generate_floor() -> void:'
if marker not in s: raise SystemExit('generate marker failed')
s=s.replace(marker,'\n\n'+helpers+marker,1)
new_gen='''func generate_floor() -> void:\n\texplored = make_bool_grid(false); visible_now = make_bool_grid(false)\n\tenemies.clear(); items.clear(); placed_traps.clear(); inventory_menu=false; inventory_selected=0\n\tunpaid_items.clear(); shop_items.clear(); shop_active=false; shop_hostile=false; merchant_type="旅商人"\n\tshopkeeper={}; shopkeeper_home=Vector2i(-1,-1); merchant_bound_turns=0; checkout_prompt=false\n\tboss_spawned=false; boss_defeated=false; clone_active=false; clone_pos=Vector2i(-1,-1); clone_steps_left=0; stairs_pos=Vector2i(-1,-1)\n\tbuild_room_corridor_floor()\n\tplayer = random_cell_in_room(floor_rooms[0])\n\tvar far_index: int = 1; var far_dist: int = -1\n\tfor i in range(1,floor_rooms.size()):\n\t\tvar c: Vector2i = floor_rooms[i].get_center(); var d: int = absi(c.x-player.x)+absi(c.y-player.y)\n\t\tif d > far_dist: far_dist=d; far_index=i\n\tstairs_pos = random_cell_in_room(floor_rooms[far_index]); map[stairs_pos.y][stairs_pos.x] = ">"\n\tif floor_no % 5 == 0 and floor_no % 10 != 0: generate_shop()\n\tvar enemy_count: int = mini(3 + int(floor_no / 12), 10)\n\tfor i in range(enemy_count): spawn_enemy(false)\n\tfor i in range(4): spawn_item()\n\tif floor_no % 10 == 0: spawn_boss()\n\tknown_enemies["max_floor"] = maxi(int(known_enemies.get("max_floor",0)),floor_no); update_visibility()\n'''
s,n=re.subn(r'func generate_floor\(\) -> void:\n.*?(?=\n\nfunc carve_safe_path)',new_gen,s,count=1,flags=re.S)
if n!=1: raise SystemExit('generate replace failed')
new_shop='''func generate_shop() -> void:\n\tshop_active=true; merchant_type="闇商人" if floor_no >= 20 and rng.randi_range(0,99) < 25 else "旅商人"\n\tvar candidates: Array = []\n\tfor r in floor_rooms:\n\t\tif not r.has_point(player) and not r.has_point(stairs_pos): candidates.append(r)\n\tvar chosen: Rect2i = candidates[rng.randi_range(0,candidates.size()-1)] if not candidates.is_empty() else floor_rooms[0]\n\tshop_rect=chosen; shopkeeper_home=chosen.get_center(); shopkeeper={"pos":shopkeeper_home,"hp":999,"atk":18+floor_no if merchant_type=="闇商人" else 12+floor_no}\n\tvar names=["薬","兵糧丸","忍気丸"]\n\tif merchant_type=="闇商人": names=["上薬","中巻物","大巻物" if floor_no>=50 else "忍気丸"]\n\tvar offsets=[Vector2i(-1,1),Vector2i(0,1),Vector2i(1,1)]\n\tfor i in range(3):\n\t\tvar ip: Vector2i = shopkeeper_home + Vector2i(offsets[i]); var price=item_shop_price(str(names[i])); var it={"pos":ip,"name":names[i],"count":1,"price":price,"shop":true}\n\t\titems.append(it); shop_items.append(it)\n'''
s,n=re.subn(r'func generate_shop\(\) -> void:\n.*?(?=\n\nfunc find_random_open_cell)',new_shop,s,count=1,flags=re.S)
if n!=1: raise SystemExit('shop replace failed')
new_vis='''func update_visibility() -> void:\n\tif not validate_grid(explored): return\n\tvisible_now = make_bool_grid(false)\n\tvar ri: int = room_index_at(player)\n\tif ri >= 0:\n\t\tvar r: Rect2i = floor_rooms[ri]\n\t\tfor y in range(maxi(0,r.position.y-1),mini(MAP_H,r.end.y+1)):\n\t\t\tfor x in range(maxi(0,r.position.x-1),mini(MAP_W,r.end.x+1)): visible_now[y][x]=true\n\telse:\n\t\tfor y in range(maxi(0,player.y-1),mini(MAP_H,player.y+2)):\n\t\t\tfor x in range(maxi(0,player.x-1),mini(MAP_W,player.x+2)): visible_now[y][x]=true\n\tfor y in range(MAP_H):\n\t\tfor x in range(MAP_W):\n\t\t\tif bool(visible_now[y][x]): explored[y][x]=true\n'''
s,n=re.subn(r'func update_visibility\(\) -> void:\n.*?(?=\n\nfunc validate_grid)',new_vis,s,count=1,flags=re.S)
if n!=1: raise SystemExit('visibility replace failed')
new_is='''func is_visible_cell(p: Vector2i) -> bool:\n\tif p.x < 0 or p.y < 0 or p.x >= MAP_W or p.y >= MAP_H: return false\n\tif validate_grid(visible_now): return bool(visible_now[p.y][p.x])\n\treturn validate_grid(explored) and bool(explored[p.y][p.x])\n'''
s,n=re.subn(r'func is_visible_cell\(p: Vector2i\) -> bool:\n.*?(?=\n\nfunc cell_center)',new_is,s,count=1,flags=re.S)
if n!=1: raise SystemExit('visible cell replace failed')
s=s.replace('\t\t"explored": explored,\n','\t\t"explored": explored,\n\t\t"floor_rooms": floor_rooms,\n',1)
s=s.replace('\tmap = data["map"]\n\texplored = data["explored"]\n','\tmap = data["map"]\n\texplored = data["explored"]\n\tfloor_rooms = data.get("floor_rooms", []) if int(data.get("version",1)) >= 7 else []\n',1)
pat=r'(\tvar origin := portrait_camera_origin\(\)\n)\tif map_visible:\n((?:\t\t.*\n)+?)(?=\tfor trap in placed_traps:)'
m=re.search(pat,s)
if m:
    body=''.join(line[1:] if line.startswith('\t') else line for line in m.group(2).splitlines(True))
    s=s[:m.start()]+m.group(1)+body+s[m.end():]
msg='\tdraw_panel(Rect2(20, 634, 680, 108), Color("#111820"), Color("#8d7740"), 1.5)\n'
if msg in s: s=s.replace(msg,'\tif map_visible:\n\t\tdraw_explored_minimap_portrait()\n\n'+msg,1)
# Direction/projectile patch runs before this patch. Harden its one Variant-producing max() inference too.
s=s.replace('\t\tvar picked_count := max(1, int(item.get("count", 1)))\n','\t\tvar picked_count: int = maxi(1, int(item.get("count", 1)))\n',1)
if s==orig: raise SystemExit('no changes made')
p.write_text(s,encoding='utf-8'); print('TORNEKO_FLOOR_MAP_PATCH PASS')
